import heapq


def dependency_solver(data, maximize, descending):
    packages = data["packages"]
    names = sorted(packages, reverse=descending)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {}
    domains = []
    for name in names:
        eligible = {row["version"]: row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])}
        rows[name] = eligible
        domains.append([-1] + sorted(eligible))

    best_vector = None
    best_install = None
    for choices in product(*domains):
        install = {name: version for name, version in zip(names, choices)
                   if version != -1}
        if any(name not in install or not bounds[0] <= install[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        edges = {}
        valid = True
        for name, version in install.items():
            active = []
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in install or not dep["min"] <= install[target] <= dep["max"]:
                    valid = False
                    break
                active.append(target)
            if not valid:
                break
            edges[name] = active
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(install):
            continue

        state, cyclic = {}, False
        def visit(name):
            nonlocal cyclic
            if state.get(name) == 1:
                cyclic = True
                return
            if state.get(name) == 2:
                return
            state[name] = 1
            for target in edges.get(name, []):
                visit(target)
            state[name] = 2
        for name in install:
            visit(name)
            if cyclic:
                break
        if cyclic:
            continue

        vector = tuple(install.get(name, -1) for name in names)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector, best_install = vector, install
    return {"versions": best_install} if best_install is not None else {"error": "unsatisfiable"}


def component_06(data):
    def rounded(n, mode):
        if mode == "half_up":
            return (2 * n + 10000) // 20000
        return n // 10000

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def component_07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    for selection in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in selection))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selection:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in selection:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        valid = True
        for _, change in sorted(events):
            active += change
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in selection)
        if (best_value is None or value > best_value
                or (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if time != dist.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, remaining))
    return {"arrival": None}


